#include <stack>

class MinStack {
private:
    std::stack<int> stack;     // 主堆疊
    std::stack<int> minStack;  // 最小值堆疊

public:
    /**
     * 雙堆疊實現 Min Stack
     * 所有操作的時間複雜度: O(1)
     * 空間複雜度: O(n)
     */

    MinStack() {
        // 建構函數
    }

    void push(int val) {
        // 推入主堆疊
        stack.push(val);

        // 如果最小值堆疊為空，或新值 ≤ 當前最小值
        if (minStack.empty() || val <= minStack.top()) {
            minStack.push(val);
        }
    }

    void pop() {
        if (!stack.empty()) {
            int top = stack.top();
            stack.pop();

            // 如果 pop 的元素是當前最小值
            if (top == minStack.top()) {
                minStack.pop();
            }
        }
    }

    int top() {
        return stack.top();
    }

    int getMin() {
        return minStack.top();
    }
};

